const fs = require("fs");
const path = require("path");

function scanDir(dir) {
  let files = [];
  for (const item of fs.readdirSync(dir)) {
    const full = path.join(dir, item);
    if (fs.statSync(full).isDirectory()) {
      files = files.concat(scanDir(full));
    } else if (full.endsWith(".js")) {
      files.push(full);
    }
  }
  return files;
}

const jsFiles = scanDir(path.resolve("app/js"));
console.log(`Scanning ${jsFiles.length} JavaScript files in app/js/ ...`);

const patterns = [
  { name: ".innerHTML =", regex: /\.innerHTML\s*=/ },
  { name: ".outerHTML =", regex: /\.outerHTML\s*=/ },
  { name: "document.write", regex: /document\.write\s*\(/ },
